sys_script_include.script:
var MSS_Custody_Event_Utils = Class.create();
MSS_Custody_Event_Utils.prototype = {

    initialize: function() {

        // Cache information based on Status of Custody in Business Process Stage Table...
        var businessProcessStageStatus = {};
        var bPSt = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage');
        bPSt.addQuery('business_process.financial_object', 'x_hsb11_mss_c_proc_mss_custody_trade');
        bPSt.query();

        while (bPSt.next()) {
            //var ctacmarket = bPSt.ctac_code.toString() + bPSt.market.toString(); commended as part of defect 1650 and added below code
            var ctacmarket = bPSt.ctac_code.toString() + bPSt.market.toString() + bPSt.business_process.process_name.toString();
            businessProcessStageStatus[ctacmarket] = {
                isActive: bPSt.active.toString(),
                isexception: bPSt.is_exception.toString(),
                isbatch: bPSt.is_batch.toString(),
                market: bPSt.market.toString(),
                terminal_stage: bPSt.terminal_stage.toString(),
                dur: bPSt.expected_duration.toString(),
                dur_ts: new GlideDateTime(bPSt.expected_duration).getNumericValue(), //get Timestamp from expected duration field
                busProcess: bPSt.business_process.toString(),
                status: bPSt.status.toString(),
                ctac: bPSt.ctac_code.toString(),
                status_sys_id: bPSt.sys_id.toString()
            };
        }

        this.businessProcessStageStatus = businessProcessStageStatus;


        // Cache information based on Stage.Status of Custody in Market Batch Process Table.
        var marketBatchProcessStatus = {};
        var mBPS = new GlideRecord('x_hsb11_mss_custod_custody_market_batch_process');
        mBPS.query();
        while (mBPS.next()) {
            // MSSCUSTODY-4281 -- update array index as status+market, and add schedule
            var batchProcess = mBPS.stage.ctac_code + mBPS.market;
            marketBatchProcessStatus[batchProcess] = {
                sDateBatch: mBPS.target_settlement_date.toString(),
                sDate1Batch: mBPS.target_settlement_date_1_batch.toString(),
                sDate2Batch: mBPS.target_settlement_date_2_batch.toString(),
                sDateafterBatch: mBPS.after_settlement_date_batch.toString(),
                sSchedule: mBPS.schedule.getDisplayValue().toString(), //MSSCUSTODY-4727
                offset: mBPS.offset_time.toString(),

                mSettlementDateBatch: mBPS.settlement_date_batch.toString(), // MSSCUSTODY 5319 - Added mapping of settlementdate batch in market time
                tSDateafterBatch: mBPS.target_settlement_date_after_batch.toString(), // MSSCUSTODY 5319 - Added mapping of target after settlement date batch
            };
        }

        this.marketBatchProcessStatus = marketBatchProcessStatus;


        // Cache information of Custody Location Code table based on the Location code in the table
        var locationCodeRecord = {};
        var lCR = new GlideRecord('x_hsb11_mss_c_proc_custody_location_code');
        lCR.query();
        while (lCR.next()) {
            var locationMarket = lCR.location_code.toString() + lCR.owning_business.toString();
            locationCodeRecord[locationMarket] = {
                locationCodeID: lCR.sys_id.toString()
            };
        }

        this.locationCodeRecord = locationCodeRecord;


        // Cache information of Curreny Table based on the code in the table
        var currencyCodeTableRecord = {};
        var currRec = new GlideRecord('fx_currency');
        currRec.query();
        while (currRec.next()) {
            currencyCodeTableRecord[currRec.code] = {
                settlementAmountCurrency: currRec.sys_id.toString()
            };
        }

        this.currencyCodeTableRecord = currencyCodeTableRecord;


        // Cache information of Custody Reason Code table based on the Reason code in the table
        var reasonCodeRecord = {};
        var reasonCR = new GlideRecord('x_hsb11_mss_c_proc_custody_reason_code');
        reasonCR.query();
        while (reasonCR.next()) {
            var ctacReason = reasonCR.reason_code.toString() + reasonCR.owning_business.toString();
            reasonCodeRecord[ctacReason] = {
                reasonCodeId: reasonCR.sys_id.toString()
            };
        }

        this.reasonCodeRecord = reasonCodeRecord;

    },

    //Process events that are in Processing status from selected queue.
    processEventQueue: function(queue) {

        var tradeLogs = []; //MSSCUSTODY-8224
        var tradeData = gs.getProperty('x_hsb11_mss_custod.tradeDataConfigs'); //MSSCUSTODY-8224
        tradeData = JSON.parse(tradeData); //MSSCUSTODY-8224

        var currentStatus;
        var etc_service = '';
        // var addAttrObj = {};
        var mssevt = new GlideRecord('x_hsb11_mss_custod_mss_custody_event_inbound_staging');
        mssevt.addEncodedQuery('queue_id=' + queue + '^processing_status=Processing'); ////MSSCUSTODY-8224 - converted to encoded query for better processing
        mssevt.orderBy('sys_created_on');
        mssevt.query();
        while (mssevt.next()) {

            var tradeDetails = JSON.parse(mssevt.trade_details);
            var OwningBusinessName = tradeDetails['OwningBusinessName'].toString();
            mssevt.owning_business = OwningBusinessName;
            var region = this.getOwningBusinessRegion(OwningBusinessName, mssevt.object_id); //MSSCUSTODY-3037: Create region field to trade form  ////MSSCUSTODY-8224 - added additional Attributes
            var tradeLifeCycle = gs.getProperty('x_hsb11_mss_custod.owning_business_core');
            //var tradeCashStock = gs.getProperty('x_hsb11_mss_custod.owning_business_stock');
            var eventOwningBusinessCore = mssevt.business_event_status + OwningBusinessName + tradeLifeCycle;
            var tradeIdentification = tradeDetails['HSBCTransactionIdentification'] ? tradeDetails['HSBCTransactionIdentification'].toString() : ""; //MSSCUSTODY-7530 ////MSSCUSTODY-8224 - Position changed to global for easy acess no other change

            if (mssevt.event_type == 'SWIFT_EVENT') {
                var swift = new x_hsb11_mss_custod.MSS_Custody_Swift_Event_Utils();
                var swftSourceSystemTimeStamp = tradeDetails['MessageSourceTimestamp'].toString();
                var swftSourceSystemTimeStampUtc = tradeDetails['MessageSourceTimestampUtc'].toString(); // MSSCUSTODY-2524:Timezone changes to UTC to store market
                var securities_account = tradeDetails['SenderIdentification'].toString();
                var instruction_source = tradeDetails['MessageChannelType'].toString();
                var messageProcessingStatus = tradeDetails['MessageProcessingStatus'] ? tradeDetails['MessageProcessingStatus'].toString() : ""; //MSSCUSTODY-7630

                if (this.businessProcessStageStatus[eventOwningBusinessCore] == undefined || this.businessProcessStageStatus[eventOwningBusinessCore]["isActive"] == "false") {

                    mssevt.processing_status = 'Error'; //As part of MSSCUSTODY-5260
                    if (this.businessProcessStageStatus[eventOwningBusinessCore] == undefined) {
                        mssevt.error_description = "Record for business event status '" + mssevt.business_event_status + "' for given owning business '" + OwningBusinessName + "' and for given trade life cycle '" + tradeLifeCycle + "' is not present in 'Business Process Stages' table"; //As part of MSSCUSTODY-5260
                    } else {
                        mssevt.error_description = "Record for business event status '" + mssevt.business_event_status + "' for given owning business '" + OwningBusinessName + "' and for given trade life cycle '" + tradeLifeCycle + "' is present in 'Business Process Stages' table with inActive state"; //As part of MSSCUSTODY-5260
                    }
                } else {
                    var stgstatus = this.businessProcessStageStatus[eventOwningBusinessCore]["status_sys_id"];
                    var isExceptionSwft = this.businessProcessStageStatus[eventOwningBusinessCore]["isexception"];
                    //currentStatus will store the value of executeEvent function to update in Custody Inbound Staging Table             
                    currentStatus = swift.executeSwiftEvent(mssevt.object_id, mssevt.technical_uuid, mssevt.source_system, mssevt.object_type, mssevt.business_event_status, stgstatus, mssevt.unity_updated_timestamp, swftSourceSystemTimeStamp, OwningBusinessName, securities_account, instruction_source, mssevt.instruction_receipt_date_time, isExceptionSwft, swftSourceSystemTimeStampUtc, region, tradeIdentification, messageProcessingStatus); //MSSCUSTODY-7530 - tradeIdentification added //MSSCUSTODY-7630 - messageProcessingStatus added
                    mssevt.processing_status = currentStatus;

                }
                mssevt.update();

            } else {
                try {
                    var transType = ["RECEIVE VERSUS PAYMENT", "RECEIVE FREE", "DELIVER FREE", "DELIVER VERSUS PAYMENT", "STOCK LOAN", "STOCK LOAN RETURN", "REDEMPTION", "SWITCH TO", "SWITCH FROM", "CORPORATE DELIVER", "CORPORATE RECEIVE", "NET RECEIVE", "NET DELIVER"]; //GR5
                    var OtherBusinessName = tradeDetails['OtherBusinessName'].toString();
                    var sourceSystemName = tradeDetails['SourceSystemName'].toLowerCase().toString(); //GR5
                    var expectedSettlementDate = tradeDetails['ExpectedSettlementDate'];
                    var clientTransactionIdentification = tradeDetails['ClientTransactionIdentification'].toString();
                    var counterpartyIdentification = tradeDetails['CounterpartyIdentification'].toString();
                    var sourceOfInstructionType = tradeDetails['SourceOfInstructionType'].toString();
                    var linkedTransactionIdentification = tradeDetails['LinkedTransactionIdentification'].toString();
                    var sameDaySettlementIndicator = tradeDetails['SameDaySettlementIndicator'].toString();
                    var safekeepingAccountIdentification = tradeDetails['SafekeepingAccountIdentification'].toString();
                    var financialInstrumentIdentificationPrimaryIdentifier = tradeDetails['FinancialInstrumentIdentificationPrimaryIdentifier'].toString();
                    var settlementAmount = tradeDetails['SettlementAmount'].toString();
                    var settlementAmountCurrency = tradeDetails['SettlementAmountCurrency'].toString();
                    var settlementQuantity = tradeDetails['SettlementQuantity'].toString();
                    var internalAccountTransferAccountIdentification = tradeDetails['InternalAccountTransferAccountIdentification'].toString();
                    var internalAccountTransferTransactionIdentification = tradeDetails['InternalAccountTransferTransactionIdentification'].toString();
                    //GR5 4240
                    var tradeDate = tradeDetails['TradeDate'] ? tradeDetails['TradeDate'].toString() : "";
                    var systemTransactionIdenfication = tradeDetails['SystemTransactionIdentification'].toString();
                    var sourceSystemTransactionType = tradeDetails['SourceSystemTransactionType'].toString();

                    //MSSCUSTODY - 8224 Modified as configurable
                    var commonID = '';
                    if (tradeData.commonIdentificationMarket.indexOf(OwningBusinessName) > -1) {
                        gs.info('Within Market');
                        commonID = tradeDetails['CommonIdentification'] ? tradeDetails['CommonIdentification'].toString() : "";
                    } else {
                        commonID = '';
                    }

                    if (tradeData.transactionType.indexOf(sourceSystemTransactionType) > -1) { //MSSCUSTODY-8224
                        sourceSystemTransactionType = sourceSystemTransactionType.toString().replaceAll(" ", ""); //removing spaces to identify the exact value from property
                        sourceSystemTransactionType = tradeData[sourceSystemTransactionType]; //final value as RVP or DVP from system property
                    } else if (tradeData.transTypeTag.indexOf(sourceSystemTransactionType) > -1) {
                        sourceSystemTransactionType = sourceSystemTransactionType; //default handling //MSSCUSTODY-8224
                    } else {
                        sourceSystemTransactionType = sourceSystemTransactionType; //default handling //MSSCUSTODY-8224
                        var sourceTransLog = "-->Transaction type received as " + sourceSystemTransactionType + "\n";
                        this.tradeInvalidDataLogs(sourceTransLog, mssevt.object_id);

                    }
                    //MSSCUSTODY - 8224 Modified as configurable

                    //MSSCUSTODY-8224
                    var tradeCoreStatus = tradeDetails['TradeBusinessStatus'].toString();
                    var tradeStockStatus = tradeDetails['TradeEconomicAvailabilityStatus'].toString();
                    var poolIdentification = tradeDetails['PoolIdentification'].toString();
                    var associatedAccountIdentification = tradeDetails['AssociatedAccountIdentification'].toString();
                    var associatedSubAccountIdentification = tradeDetails['AssociatedSubAccountIdentification'].toString();
                    var settlementInstructionCancellationStatus = tradeDetails['SettlementInstructionCancellationStatus'].toString();
                    var additionalUnexecutionReasonInformation = tradeDetails['AdditionalUnexecutionReasonInformation'].toString();
                    var repurchaseTransactionIdentification = tradeDetails['RepurchaseTransactionIdentification'].toString();
                    var repurchaseLegType = tradeDetails['RepurchaseLegType'].toString();
                    var safekeepingAccountName = tradeDetails['SafekeepingAccountName'].toString();
                    //GR5 4240
                    var effectiveSettlementDate = tradeDetails['EffectiveSettlementDate'] ? tradeDetails['EffectiveSettlementDate'].toString() : "";
                    var counterpartyName = tradeDetails['CounterpartyName'].toString();
                    var customerIdentification = tradeDetails['CustomerIdentification'].toString();
                    var settlementInstructionProcessingAdditionalDetails = tradeDetails['SettlementInstructionProcessingAdditionalDetails'].toString();
                    //GR5 4240
                    var settlement_Date = tradeDetails['SettlementDate'] ? tradeDetails['SettlementDate'].toString() : "";
                    var sourceSystemLastUpdatedDateTime = tradeDetails['SourceSystemLastUpdatedDateTime'].toString();
                    var financialInstrumentIdentificationDescription = tradeDetails['FinancialInstrumentIdentificationDescription'].toString();
                    var crossBusinessTransactionIdentification = tradeDetails['CrossBusinessTransactionIdentification'].toString();
                    var clientEntityIdentification = tradeDetails['ClientEntityIdentification'].toString();
                    var clientGroupIdentification = tradeDetails['ClientGroupIdentification'].toString();
                    var transactionReferenceAmount = tradeDetails['TransactionReferenceAmount'].toString();
                    var transactionReferenceAmountCurrency = tradeDetails['TransactionReferenceAmountCurrency'].toString();
                    var securitiesRtgsIndicator = tradeDetails['SecuritiesRtgsIndicator'].toString(); //MSSCUSTODY-3174 : Populate variable on Inbound
                    var securitiesLendingIndicator = tradeDetails['SecuritiesLendingIndicator'].toString(); //MSSCUSTODY-3174 : Populate variable on Inbound
                    var securitiesBorrowingIndicator = tradeDetails['SecuritiesBorrowingIndicator'].toString(); //MSSCUSTODY-3174 : Populate variable on Inbound

                    // MSSCUSTODY-3591 : Coverting below fields from On-demand to Grid
                    var stp_indicator = tradeDetails['StraightThroughProcessedIndicator'] ? tradeDetails['StraightThroughProcessedIndicator'].toString() : "";
                    // var account_standing_instructions = tradeDetails['SecuritiesAccountStandingInstructionDetails'] ? tradeDetails['SecuritiesAccountStandingInstructionDetails'].toString() : "";
                    var stlpos_no = tradeDetails['MarketInfrastructureTransactionIdentification'] ? tradeDetails['MarketInfrastructureTransactionIdentification'].toString() : "";
                    var si_payment_indicator = tradeDetails['HKSettlementInstructionPaymentIndicator'] ? tradeDetails['HKSettlementInstructionPaymentIndicator'].toString() : "";
                    var link_indicator = tradeDetails['LinkedIndicator'] ? tradeDetails['LinkedIndicator'].toString() : "";
                    var local_security_code = tradeDetails['FinancialInstrumentIdentificationLocalSecurityCode'] ? tradeDetails['FinancialInstrumentIdentificationLocalSecurityCode'].toString() : "";
                    var customer_instruction_received = tradeDetails['ClientInstructionReceivedIndicator'] ? tradeDetails['ClientInstructionReceivedIndicator'].toString() : "";
                    var cash_payment_method = tradeDetails['CashPaymentMethod'] ? tradeDetails['CashPaymentMethod'].toString() : "";
                    var counterparty_cash_account_id = tradeDetails['CounterpartyCashAccountIdentification'] ? tradeDetails['CounterpartyCashAccountIdentification'].toString() : "";
                    var deal_price_currency = tradeDetails['DealPriceAmountCurrency'] ? tradeDetails['DealPriceAmountCurrency'].toString() : "";
                    var deal_price = tradeDetails['DealPriceAmount'] ? tradeDetails['DealPriceAmount'].toString() : "";
                    var external_reference = tradeDetails['InstructionIdentification'] ? tradeDetails['InstructionIdentification'].toString() : "";
                    var exchange_reference2 = tradeDetails['ExchangeIdentification'] ? tradeDetails['ExchangeIdentification'].toString() : "";
                    var buyerName = tradeDetails['BuyerName'] ? tradeDetails['BuyerName'].toString() : "";
                    var sellerName = tradeDetails['SellerName'] ? tradeDetails['SellerName'].toString() : "";
                    var buyer_seller = buyerName + ' / ' + sellerName;
                    var receiverAccount = tradeDetails['ReceiversCustodianAccountIdentification'] ? tradeDetails['ReceiversCustodianAccountIdentification'].toString() : "";
                    var delivererAccount = tradeDetails['DeliverersCustodianAccountIdentification'] ? tradeDetails['DeliverersCustodianAccountIdentification'].toString() : "";
                    var u_client_s_deliverer_receiverer_account = receiverAccount + ' / ' + delivererAccount;
                    var receiver_custodian_bic = tradeDetails['ReceiversCustodianBic'] ? tradeDetails['ReceiversCustodianBic'].toString() : "";
                    var deliverer_custodian_bic = tradeDetails['DeliverersCustodianBic'] ? tradeDetails['DeliverersCustodianBic'].toString() : "";
                    var receiver_deliverer_custodian_bic = receiver_custodian_bic + '/' + deliverer_custodian_bic;
                    var counterparty_s_associate_account = tradeDetails['CounterpartyAssociatedAccountIdentification'] ? tradeDetails['CounterpartyAssociatedAccountIdentification'].toString() : "";
                    var hold_matched_si_indicator = tradeDetails['HoldMatchedSettlementInstructionIndicator'] ? tradeDetails['HoldMatchedSettlementInstructionIndicator'].toString() : "";
                    var remarks = tradeDetails['TradeDescription'] ? tradeDetails['TradeDescription'].toString() : "";
                    var ent_opid = tradeDetails['CaptureUserIdentification'] ? tradeDetails['CaptureUserIdentification'].toString() : "";
                    var quantity_type = tradeDetails['QuantityType'] ? tradeDetails['QuantityType'].toString() : "";

                    //added as part of 7123 --> coverting on-demand to grid
                    var si_purpose_code = tradeDetails['HKSettlementInstructionPurposeCode'] ? tradeDetails['HKSettlementInstructionPurposeCode'].toString() : "";
                    var propriety_code = tradeDetails['CounterpartyDataSourceSchemeCode'] ? tradeDetails['CounterpartyDataSourceSchemeCode'].toString() : "";
                    var data_source_scheme = tradeDetails['CounterpartyDataSourceSchemeType'] ? tradeDetails['CounterpartyDataSourceSchemeType'].toString() : "";

                    // MSSCUSTODY-3591 : Created new fields 
                    var customer_cancellation_reference = tradeDetails['ClientCancellationIdentification'] ? tradeDetails['ClientCancellationIdentification'].toString() : "";
                    var security_account_type = tradeDetails['SafekeepingAccountType'] ? tradeDetails['SafekeepingAccountType'].toString() : "";
                    var u_fx_indicator = tradeDetails['FxIndicator'] ? tradeDetails['FxIndicator'].toString() : "";
                    var nssc = tradeDetails['SuppressStockSufficiencyCheckIndicator'] ? tradeDetails['SuppressStockSufficiencyCheckIndicator'].toString() : "";
                    var sett_type = tradeDetails['DepositorySettlementType'] ? tradeDetails['DepositorySettlementType'].toString() : "";
                    var iss_ind = tradeDetails['BursaSettlementType'] ? tradeDetails['BursaSettlementType'].toString() : "";
                    var reg = tradeDetails['RegistrationCode'] ? tradeDetails['RegistrationCode'].toString() : "";
                    var rgst_reg = tradeDetails['RegistrationIndicator'] ? tradeDetails['RegistrationIndicator'].toString() : "";

                    //MSSCUSTODY-6479
                    var trade_account_model = tradeDetails['TradeAccountModelType'] ? tradeDetails['TradeAccountModelType'].toString() : "";
                    var single_sided_indicator = tradeDetails['SingleSidedIndicator'] ? tradeDetails['SingleSidedIndicator'].toString() : "";

                    //MSSCUSTODY-5992 : Converting fields to Grid
                    var counterparty_reference = tradeDetails['TradeIdentification'] ? tradeDetails['TradeIdentification'].toString() : "";
                    var switch_indicator = tradeDetails['InternalAccountTransferIndicator'] ? tradeDetails['InternalAccountTransferIndicator'].toString() : "";
                    var counterparty_cash_account_name = tradeDetails['CounterpartyCashAccountName'] ? tradeDetails['CounterpartyCashAccountName'].toString() : "";
                    var account_standing_instructions = tradeDetails['SecuritiesAccountStandingInstructionDetails'] ? tradeDetails['SecuritiesAccountStandingInstructionDetails'].toString() : "";
                    if (account_standing_instructions.length > 2100) { //MSSCUSTODY-7182
                        account_standing_instructions = account_standing_instructions.substring(0, 2100);
                    }
                    var suspense_account_number = tradeDetails['InternalAccountTransferSuspenseCashAccountIdentification'] ? tradeDetails['InternalAccountTransferSuspenseCashAccountIdentification'].toString() : "";
                    var exch_rate = tradeDetails['FxRate'] ? tradeDetails['FxRate'].toString() : "";

                    //MSSCUSTODY-8060 New
                    var si_proc_status = tradeDetails['SettlementInstructionProcessingStatus'] ? tradeDetails['SettlementInstructionProcessingStatus'].toString() : "";

                    //MSSCUSTODY-7611
                    if (OwningBusinessName.indexOf("GC HK") > -1) {
                        var pending_cancellation_support_indicator = tradeDetails['PendingCancellationSupportedIndicator'] ? tradeDetails['PendingCancellationSupportedIndicator'].toString() : "";
                        var contractual_indicator = tradeDetails['ContractualPostedIndicator'] ? tradeDetails['ContractualPostedIndicator'].toString() : "";
                        var pending_cancellation_indicator = tradeDetails['PendingCancellationIndicator'] ? tradeDetails['PendingCancellationIndicator'].toString() : "";
                    }

                    //MSSCUSTODY-7353 : Converting fields to Grid
                    var fxcx = tradeDetails['FxOrderCancellationIndicator'] ? tradeDetails['FxOrderCancellationIndicator'].toString() : "";
                    var fx_inst_sts = tradeDetails['FxInstructionStatus'] ? tradeDetails['FxInstructionStatus'].toString() : "";
                    var av_indicator = tradeDetails['AccountingAndValuationMessageStatus'] ? tradeDetails['AccountingAndValuationMessageStatus'].toString() : "";

                    var cancellation_date = tradeDetails['CancellationDate'] ? tradeDetails['CancellationDate'].toString() : "";
                    var swift_sett_trans_cond = tradeDetails['SettlementTransactionConditionCode'] ? tradeDetails['SettlementTransactionConditionCode'].toString() : "";
                    var legacy_pre_state = tradeDetails['SourceSystemPreviousStatus'] ? tradeDetails['SourceSystemPreviousStatus'].toString() : "";
                    var bk_to_bk = tradeDetails['SettlementConfirmationAdditionalDetails'] ? tradeDetails['SettlementConfirmationAdditionalDetails'].toString() : "";


                    //MSSCUSTODY-6824 : Converting fields to Grid
                    var place_of_trad_mic = tradeDetails['PlaceOfTradeMic'] ? tradeDetails['PlaceOfTradeMic'].toString() : ""; //for non uk
                    var place_of_trad_typ_cod = tradeDetails['PlaceOfTradeTypeCode'] ? tradeDetails['PlaceOfTradeTypeCode'].toString() : ""; //for uk
                    var secIDType = tradeDetails['FinancialInstrumentIdentificationProductType'] ? tradeDetails['FinancialInstrumentIdentificationProductType'].toString() : "";

                    //GR5
                    var defaultPlaceOfSettlementBic = tradeDetails['DefaultPlaceOfSettlementBic'] ? tradeDetails['DefaultPlaceOfSettlementBic'].toString() : "";
                    var placeOfSettlementBic = tradeDetails['PlaceOfSettlementBic'] ? tradeDetails['PlaceOfSettlementBic'].toString() : defaultPlaceOfSettlementBic; //	MSSCUSTODY-5648Setting defaultvalu for PSET. 
                    var financialInstrumentIdentificationIsin = tradeDetails['FinancialInstrumentIdentificationIsin'] ? tradeDetails['FinancialInstrumentIdentificationIsin'].toString() : "";
                    var counterpartyDataSourceSchemeCode = tradeDetails['CounterpartyDataSourceSchemeCode'] ? tradeDetails['CounterpartyDataSourceSchemeCode'].toString() : "";
                    var buyerBic = tradeDetails['BuyerBic'] ? tradeDetails['BuyerBic'].toString() : "";
                    var sellerBic = tradeDetails['SellerBic'] ? tradeDetails['SellerBic'].toString() : "";
                    var buyerOrSellerBic = buyerBic + ' / ' + sellerBic;
                    var buyerDataSourceSchemeCode = tradeDetails['BuyerDataSourceSchemeCode'] ? tradeDetails['BuyerDataSourceSchemeCode'].toString() : "";
                    var sellerDataSourceSchemeCode = tradeDetails['SellerDataSourceSchemeCode'] ? tradeDetails['SellerDataSourceSchemeCode'].toString() : "";
                    var buyerSellerDataSourceScheme = buyerDataSourceSchemeCode + ' / ' + sellerDataSourceSchemeCode;
                    var cashAccountIdentification = tradeDetails['CashAccountIdentification'] ? tradeDetails['CashAccountIdentification'].toString() : "";
                    var valueDate = tradeDetails['ValueDate'] ? tradeDetails['ValueDate'].toString() : "";
                    var registrationCode = tradeDetails['RegistrationCode'] ? tradeDetails['RegistrationCode'].toString() : "";
                    var buyerAccountIdentification = tradeDetails['BuyerAccountIdentification'] ? tradeDetails['BuyerAccountIdentification'].toString() : "";
                    var sellerAccountIdentification = tradeDetails['SellerAccountIdentification'] ? tradeDetails['SellerAccountIdentification'].toString() : "";
                    var buyerOrSellerAccountIdentification = buyerAccountIdentification + ' / ' + sellerAccountIdentification;
                    var pendingCancelIationIndicator = tradeDetails['PendingCancellationIndicator'] ? tradeDetails['PendingCancellationIndicator'].toString() : "";
                    var accountBaseCurrency = tradeDetails['AccountBaseCurrency'] ? tradeDetails['AccountBaseCurrency'].toString() : "";
                    var depositoryIdentification = tradeDetails['DepositoryIdentification'] ? tradeDetails['DepositoryIdentification'].toString() : "";
                    var localCustodianIdentification = tradeDetails['LocalCustodianIdentification'] ? tradeDetails['LocalCustodianIdentification'].toString() : ""
                    var depositoryOrLocalCustodianIdentification = depositoryIdentification + localCustodianIdentification;
                    var securitiesTransactionTypeCode = tradeDetails['SecuritiesTransactionTypeCode'] ? tradeDetails['SecuritiesTransactionTypeCode'].toString() : "";
                    var fxInstructionStatus = tradeDetails['FxInstructionStatus'] ? tradeDetails['FxInstructionStatus'].toString() : "";
                    var additionalCancellationReasonInformation = tradeDetails['AdditionalCancellationReasonInformation'] ? tradeDetails['AdditionalCancellationReasonInformation'].toString() : "";
                    var counterparty = tradeDetails['CounterpartyBic'] ? tradeDetails['CounterpartyBic'] : "";
                    var counterpartyBic = counterparty + counterpartyIdentification;
                    var swiftStatus1Reason1Code = tradeDetails['SwiftStatus1Reason1Code'] ? tradeDetails['SwiftStatus1Reason1Code'] : "";
                    var gdiIdicatorValue = tradeDetails['GenerateDepositoryInstructionIndicator'] ? tradeDetails['GenerateDepositoryInstructionIndicator'] : "";

                    //few of the commented codes below has been removed as the reference was not mentioned 
                    var tradeType, instructionDateTime;

                    var tradeTypeFound = mssevt.trade_details.indexOf("SecuritiesSettlementType");
                    var instructionDateTimeFound = mssevt.instruction_receipt_date_time;

                    if (tradeTypeFound !== -1) {
                        tradeType = tradeDetails['SecuritiesSettlementType'].toString();
                    }

                    if (instructionDateTimeFound !== -1) {
                        instructionDateTime = mssevt.instruction_receipt_date_time;
                    }

                    //Added as part of MSSCUSTODY-3854 for GR5 P1b UK market

                    var priority = tradeDetails['CrestSettlementPriorityCode'] ? tradeDetails['CrestSettlementPriorityCode'] : "";
                    var fxLocation = tradeDetails['FxLocationCode'] ? tradeDetails['FxLocationCode'] : "";
                    var fxrTD = tradeDetails['FxCancellationIndicator'] ? tradeDetails['FxCancellationIndicator'] : "";
                    var contractType = tradeDetails['ContractualSettlementIndicator'] ? tradeDetails['ContractualSettlementIndicator'] : ""; // Made GRID field with 4148 and moved with 4701 to PROD

                    var locationCode, locationDescription;
                    if (OwningBusinessName.indexOf("DCC") > -1) {
                        locationCode = tradeDetails['LocationCode'].toString();
                        locationDescription = tradeDetails['LocationDescription'].toString();
                    } else if (OwningBusinessName.indexOf("GC") > -1) {
                        locationCode = tradeDetails['LocalCustodianCode'].toString();
                        locationDescription = tradeDetails['LocalCustodianDescription'].toString();
                    }

                    var eventDateTimes = GlideDateTime(mssevt.source_system_timestamp); //mssevt.source_system_timestamp;
                    var sourceDateTimeNumeric = GlideDateTime(mssevt.source_system_timestamp).getNumericValue();
                    var eventDate = mssevt.getValue('source_system_date');
                    var eventdatetimeNumeric = mssevt.unity_updated_timestamp;
                    var tradeCashStock = gs.getProperty('x_hsb11_mss_custod.owning_business_stock');
                    var eventOwningBusinessStock = tradeStockStatus + OwningBusinessName + tradeCashStock;

                    //As part of MSSCUSTODY-5260
                    var transactionReference = tradeDetails['SystemTransactionIdentification'] ? tradeDetails['SystemTransactionIdentification'] : "";
                    var transactionType = tradeDetails['SourceSystemTransactionType'] ? tradeDetails['SourceSystemTransactionType'] : "";
                    var tradeDate = tradeDetails['TradeDate'] ? tradeDetails['TradeDate'] : "";
                    var securityId = tradeDetails['FinancialInstrumentIdentificationPrimaryIdentifier'] ? tradeDetails['FinancialInstrumentIdentificationPrimaryIdentifier'] : "";

                    //code to create an anomaly case in case of unknown Status received
                    if (this.businessProcessStageStatus[eventOwningBusinessCore] == undefined) {
                        // gs.info('vb=='+tradeStockStatus);
                        mssevt.hsbc_transaction_reference = transactionReference; //As part of MSSCUSTODY-5260
                        mssevt.transaction_type = transactionType; //As part of MSSCUSTODY-5260
                        mssevt.trade_date = tradeDate; //As part of MSSCUSTODY-5260
                        mssevt.security_id = securityId; //As part of MSSCUSTODY-5260
                        mssevt.processing_status = 'Error';
                        // mssevt.status = 'Pending'; //As part of MSSCUSTODY-5260
                        mssevt.error_description = "Record for business event status '" + mssevt.business_event_status + "' for given owning business '" + OwningBusinessName + "' and for given trade life cycle '" + tradeLifeCycle + "' is not present in 'Business Process Stages' table"; //As part of MSSCUSTODY-5260

