                crttrade.fx_status = fxInstructionStatus; //MSSCUSTODY-3854 P1B change, mapped to new field Fx status																									 
                crttrade.amortised_value = settlementQuantity;
                crttrade.reason_description_remarks_canc = additionalCancellationReasonInformation;
                crttrade.counterparty_code = counterpartyBic;
                crttrade.u_primary_swift_reason_code_1 = swiftStatus1Reason1Code;
                crttrade.snis_crest = gdiIdicatorValue;
                crttrade.swift = gdiIdicatorValue;
                crttrade.settlement_date = settlement_Date; //added as a part of 4067 UDM - Settlement Date // similar mapping as contractual settlement date

                // MSSCUSTODY-3854 P1B changes
                crttrade.fx_location = fxLocation;
                crttrade.fxr_td = fxrTD;
                crttrade.priority = priority;
                crttrade.contract_type = contractType;

                // 3591
                crttrade.ent_opid = ent_opid;
                crttrade.remarks = remarks;

                // MSSCUSTODY-4732
                crttrade.trade_ccy = settlementAmountCurrency;
                crttrade.acct_ccy = accountBaseCurrency;
            }

            return crttrade.insert();
            //        }
        } catch (e) {
            gs.error("Error from Script Include MSS_Custody_Event_Utils - insertTradeRecord (for trade " + objectid + "): " + e.message);
        }
    },

    //MSSCUSTODY-6201
    getReasonCodeDescription: function(rcode, objectid, legacyreasoncode) { //MSSCUSTODY-8224 - object ID added extra
        var description = '';
        var grCode = new GlideRecord('x_hsb11_mss_c_proc_custody_reason_code');
        grCode.addQuery('sys_id', rcode);
        grCode.query();
        if (grCode.next()) {
            description = grCode.getValue('reason_code') + " - " + grCode.getValue('reason_description');
        } else { //MSSCUSTODY-8224
            var reasonCodeLog;
            if (legacyreasoncode != '') {
                reasonCodeLog = "-->Reason Code " + legacyreasoncode + " does not exsist in iQube so reason code description population failed" + "\n";
                this.tradeInvalidDataLogs(reasonCodeLog, objectid);
            } else {
                reasonCodeLog = "-->Reason Code received as empty" + "\n";
                this.tradeInvalidDataLogs(reasonCodeLog, objectid);
            }
        } //MSSCUSTODY-8224

        return description.toString();

    },

    updateBPICore: function(gdt, objectid, objecttype, eventstatus, source, TechId, isException, eventdatetimeNumeric, OtherBusinessName, OwningBusinessName, businessProcess, terminal_stage, eventdatetime, ExpectedSettlementDate, locationDescription, isBatch, cDate, eventDate, stg_time, stg_status) {
        try {
            var initGdt = new GlideDateTime();
            initGdt.setValue(gdt);

            var initGdtINT = initGdt.getNumericValue();

            var updBPI = new GlideRecord('x_hsb11_mss_custod_mss_custody_business_process_instance');
            updBPI.addQuery('object_id', objectid);
            updBPI.query();
            if (updBPI.next()) {

                updBPI.object_type = objecttype;
                updBPI.source_system = source;
                updBPI.other_business = OtherBusinessName;
                updBPI.owning_business = OwningBusinessName;
                updBPI.business_process_definition = businessProcess;
                updBPI.recent_technical_uuid = TechId;
                updBPI.settlement_date = ExpectedSettlementDate;
                updBPI.market_code = locationDescription;
                updBPI.unity_updated_timestamp = eventdatetimeNumeric;
                updBPI.core_business_event_status = eventstatus;
                updBPI.core_stage_reference = stg_status;
                updBPI.core_source_system_last_update = eventdatetime;

                if (isException == "true") {
                    updBPI.is_core_status_exception = true;
                    updBPI.is_batch = false;
                    updBPI.core_expected_transition_time = '';
                } else if (isBatch == "true") {
                    updBPI.is_batch = true;

                    if ((ExpectedSettlementDate < cDate) || (ExpectedSettlementDate < eventDate)) {
                        updBPI.is_core_status_exception = true;
                        updBPI.core_expected_transition_time = '';
                    } else {
                        //MSSCUSTODY-4281 include market value in the index when looking up the market batch record from the array
                        var batchMarket = OwningBusinessName.split(' ');
                        var market = batchMarket[1] + ' ' + batchMarket[0];

                        if (this.marketBatchProcessStatus[eventstatus + market] != undefined) {


                            var CoreExpectedTransitionTime = this.getCoreExpectedTransitionTime(eventstatus, market, eventdatetime, ExpectedSettlementDate, eventDate);

                            if (CoreExpectedTransitionTime == 'Exception') {
                                updBPI.is_core_status_exception = true;
                                updBPI.core_expected_transition_time = '';
                            } else {
                                updBPI.is_core_status_exception = false;
                                updBPI.core_expected_transition_time.setDisplayValue(CoreExpectedTransitionTime);
                            }
                        }
                    }
                } else if (stg_time != 0) {
                    updBPI.is_core_status_exception = false;
                    updBPI.is_batch = false;
                    updBPI.core_expected_transition_time = initGdt;
                } else {
                    updBPI.is_core_status_exception = false;
                    updBPI.is_batch = false;
                    updBPI.core_expected_transition_time = '';
                }

                if (terminal_stage == "true") {
                    updBPI.is_core_terminal_status = true;
                } else {
                    updBPI.is_core_terminal_status = false;
                }

                updBPI.update();
            }
        } catch (e) {
            gs.error("Error from Script Include MSS_Custody_Event_Utils - updateBPICore (for trade " + objectid + "): " + e.message);
        }
    },

