    //MSSCUSTODY-4281 -- add market as input parameter in this function for looking up  market batch record, and taking the next day Batch timings for the screnario that all today's batch are already processed
    getCoreExpectedTransitionTime: function(eventstatus, market, eventdatetime, ExpectedSettlementDate, eventDate) {
        try {
            //Fetch all the required variables from Market Bath Process table
            var eventstatusmarket = eventstatus + market; //MSSCUSTODY-4281 -- include market in the index to look up the record in array
            var settlementDateBatch = this.marketBatchProcessStatus[eventstatusmarket]['sDateBatch'];
            var settlementDate1Batch = this.marketBatchProcessStatus[eventstatusmarket]['sDate1Batch'];
            var settlementDate2Batch = this.marketBatchProcessStatus[eventstatusmarket]['sDate2Batch'];
            var settlementDateafterBatch = this.marketBatchProcessStatus[eventstatusmarket]['sDateafterBatch'];

            // MSSCUSTODY 5319 - Fetch values of Settlement date batch in market time and target after settlement date batch
            var marketSettlementDateBatch = this.marketBatchProcessStatus[eventstatusmarket]['mSettlementDateBatch'];
            var targetAfterSettlementDateBatch = this.marketBatchProcessStatus[eventstatusmarket]['tSDateafterBatch'];

            //MSSCUSTODY-4727 
            var schedule = this.marketBatchProcessStatus[eventstatusmarket]['sSchedule'];

            var sluDate = new GlideDateTime(eventdatetime);
            var sDate = sluDate.getLocalDate();
            var settlmntDate = new GlideDateTime(ExpectedSettlementDate); //This will always come as same date but time to 00:00:00
            var differenceIndate = GlideDateTime.subtract(sDate, settlmntDate).getDayPart();

            //MSSCUSTODY-4727
            var coreExpectedTransitionTime = 'Exception';

            // MSSCUSTODY 5319 - Convert current time and settlement time to the same schedule
            var currentTime = new GlideScheduleDateTime(eventdatetime);
            currentTime.setTimeZone("UTC");
            var settlementDateTime = new GlideDateTime(ExpectedSettlementDate);

            // MSSCUSTODY 5319 - Convert current time to the market's time zone
            var gdtCurrentTime = new GlideScheduleDateTime(currentTime);
            gdtCurrentTime.setTimeZone(schedule);

            // MSSCUSTODY 5319 - Convert settlement time to the market's time zone
            var gdtSettlementDate = new GlideScheduleDateTime(settlementDateTime);
            gdtSettlementDate.setTimeZone(schedule);


            if ((differenceIndate >= 2 && gs.nil(settlementDate2Batch)) || (differenceIndate == 1 && gs.nil(settlementDate1Batch))) {
                if (gs.nil(settlementDateBatch)) {
                    //settlementDateBatch no value, check settlementDateafterBatch
                    coreExpectedTransitionTime = this.caculateCoreExpectedTransDateTime(targetAfterSettlementDateBatch, ExpectedSettlementDate, schedule, -1, eventstatusmarket); // MSSCSUTODY 5319 - Updated function call with targetAfterSettlementDateBatch instead of settlementDateafterBatch ////MSSCUSTODY-6274
                    return coreExpectedTransitionTime;
                }
                // MSSCUSTODY 5319 - Settlement Date-2 batch is empty then consider Settlement Date-1 batch as core expected transitition time if present
                else if (!gs.nil(settlementDate1Batch)) {
                    coreExpectedTransitionTime = this.caculateCoreExpectedTransDateTime(settlementDate1Batch, ExpectedSettlementDate, schedule, 0, eventstatusmarket); // MSSCSUTODY 5319 - Updated function call with targetAfterSettlementDateBatch instead of settlementDateafterBatch   ////MSSCUSTODY-6274
                    return coreExpectedTransitionTime;
                } else {
                    // settlementDateBatch has value, could be exception ( SD 00:00), or first time of the batch.
                    coreExpectedTransitionTime = this.caculateCoreExpectedTransDateTime(settlementDateBatch, ExpectedSettlementDate, schedule, 0, eventstatusmarket); ////MSSCUSTODY-6274
                    return coreExpectedTransitionTime;
                }
            } else if ((differenceIndate > 2 && !gs.nil(settlementDate2Batch))) { // Added as part of MSSCUSTODY-7080
                var parts = ExpectedSettlementDate.split("-");
                var day = parseInt(parts[2], 10) - 2;
                parts[2] = day.toString().padStart(2, '0');
                var reducedSettlementDateStr = parts.join("-");
                coreExpectedTransitionTime = this.caculateCoreExpectedTransDateTime(settlementDate2Batch, reducedSettlementDateStr, schedule, 2, eventstatusmarket); // MSSCSUTODY 5319 - Updated function call with targetAfterSettlementDateBatch instead of settlementDateafterBatch ////MSSCUSTODY-6274
                return coreExpectedTransitionTime;
            } else if (differenceIndate == 0) {
                if (gs.nil(settlementDateBatch)) {
                    //settlementDateBatch is blank, check settlementDateafterBatch
                    coreExpectedTransitionTime = this.caculateCoreExpectedTransDateTime(targetAfterSettlementDateBatch, ExpectedSettlementDate, schedule, -1, eventstatusmarket); // MSSCSUTODY 5319 - Updated function call with targetAfterSettlementDateBatch instead of settlementDateafterBatch //MSSCUSTODY-6274
                    return coreExpectedTransitionTime;
                } else if (settlementDateBatch == 'Exception' || settlementDateBatch == 'aNaN') {
                    // settlementDateBatch is Exception, create case immediately.
                    return coreExpectedTransitionTime;
                }
                // has value return to original logic
            } else if (gs.nil(targetAfterSettlementDateBatch)) {
                //not expect.
                gs.error("MSSCUSTODY-4727: differenceIndate:" + differenceIndate + ".settlementDate2Batch:" + settlementDate2Batch + ".settlementDate1Batch:" + settlementDate1Batch + ".settlementDateBatch:" + settlementDateBatch + ".settlementDateafterBatch:" + settlementDateafterBatch);
                return coreExpectedTransitionTime;
            }

            var appropriateBatch;
            var nextDayBatch;

            if (differenceIndate == 0) {
                appropriateBatch = settlementDateBatch;
                nextDayBatch = targetAfterSettlementDateBatch;
            } else if (differenceIndate == 1) {
                appropriateBatch = settlementDate1Batch;
                nextDayBatch = settlementDateBatch;
            } else if (differenceIndate == 2) {
                appropriateBatch = settlementDate2Batch;
                nextDayBatch = settlementDate1Batch;
            } else if (differenceIndate > 2) {
                appropriateBatch = settlementDate2Batch;
                nextDayBatch = settlementDate2Batch;
            } else if (differenceIndate < 0) {
                //appropriateBatch = 'Exception';  //MSSCUSTODY-4281 updated to take value from config instead of hardcode
                appropriateBatch = targetAfterSettlementDateBatch;
            }

            //MSSCUSTODY 5319 - If the event time is after the settlement date batch time, create the case immediately
            if (differenceIndate === 0 && marketSettlementDateBatch === '0000') {
                if (gdtCurrentTime.getGlideDateTime().getNumericValue() > gdtSettlementDate.getGlideDateTime().getNumericValue()) {
                    return 'Exception'; // Create the case immediately
                }
            }
            if (appropriateBatch == 'Exception' || appropriateBatch == 'aNaN') { //MSSCUSTODY-4281 In market process config table, 'aNaN' may appear in the Target... filed, if its batch setup is 'Exception'

                return 'Exception';
            }

            return this.getCoreExpectedTransDateTime(eventdatetime, ExpectedSettlementDate, appropriateBatch, nextDayBatch, eventstatusmarket, eventDate, schedule); // MSSCUSTODY 5319 - Added schedule in function declaration

        } catch (e) {
            gs.error("Error from Script Include MSS_Custody_Event_Utils - getCoreExpectedTransitionTime " + e.message);
        }
    },

    //MSSCUSTODY-4727
    //batchtype, 2, 1, 0 batch, -1 = after batch
    caculateCoreExpectedTransDateTime: function(appropriateBatch, settlmntDate, schedule, batchType, eventstatusmarket) { ////MSSCUSTODY-6274
        try {
            //default if no rules matched. settlmntDate consider as local time.
            var coreExpectedTransitionTime = 'Exception';
            var marketSettlementBatch = this.marketBatchProcessStatus[eventstatusmarket]['mSettlementDateBatch'];
            var settlementDateBatch = this.marketBatchProcessStatus[eventstatusmarket]['sDateBatch'];
            //Sample: 0900,1100,1300,1500,1700
            if (appropriateBatch.indexOf(',') > -1) {
                var ttime = appropriateBatch.split(',');
                var tt = ttime[0];
                var hour = tt.slice(0, -2).padStart(2, '0');
                var min = tt.slice(-2).padStart(2, '0');
                var timef = hour + ":" + min + ":00"; // + sec;

                var nxtTime = settlmntDate + " " + timef;
                coreExpectedTransitionTime = new GlideDateTime(nxtTime);

            } else if (appropriateBatch == 'Exception' || appropriateBatch == 'aNaN') {
                //Set local time
                var localSettlmntDate = new GlideDateTime(settlmntDate);
                if (batchType == -1) {
                    localSettlmntDate.addDaysLocalTime(1);
                }
                var gdtSettlmntDate = new GlideScheduleDateTime(localSettlmntDate);
                gdtSettlmntDate.setTimeZone(schedule);
                //gs.info("MSSCUSTODY-4727:1" + gdtSettlmntDate + ".schedule:" + schedule);

                //convert to UKT
                gdtSettlmntDate.setTimeZone("UTC");
                //gs.info("MSSCUSTODY-4727:2" + gdtSettlmntDate + ".schedule:" + schedule);

                coreExpectedTransitionTime = gdtSettlmntDate.getGlideDateTime(); //.getDisplayValue();
            } else if ((appropriateBatch === settlementDateBatch) && marketSettlementBatch === '0000') { //MSSCUSTODY-6274
                var hour = appropriateBatch.slice(0, -2).padStart(2, '0');
                var min = appropriateBatch.slice(-2).padStart(2, '0');
                var timef = hour + ":" + min + ":00";

                var nxtTime = settlmntDate + " " + timef;

                coreExpectedTransitionTime = new GlideDateTime(nxtTime);
                coreExpectedTransitionTime.addDaysLocalTime(-1);
            } else {
                // MSSCUSTODY 5319 - Handle single batch value
                var hour = appropriateBatch.slice(0, -2).padStart(2, '0');
                var min = appropriateBatch.slice(-2).padStart(2, '0');
                var timef = hour + ":" + min + ":00";

                var nxtTime = settlmntDate + " " + timef;

                coreExpectedTransitionTime = new GlideDateTime(nxtTime);
                //   coreExpectedTransitionTime.addDaysLocalTime(-1);      ////MSSCUSTODY-6274
            }
            return coreExpectedTransitionTime;
        } catch (e) {
            gs.error("Error from Script Include MSS_Custody_Event_Utils - caculateCoreExpectedTransDateTime: " + e.message);
        }
    },

    //MSSCUSTODY-4281 -- add market as input parameter of this function and used to look up the market batch record
    getCoreExpectedTransDateTime: function(eventDateTime, settlementDate, appropriateBatch, nextDayBatch, eventstatusmarket, eventDate, schedule) { // MSSCUSTODY 5319 - Added schedule in function definition
        try {
            var offse;
            try {
                offse = this.marketBatchProcessStatus[eventstatusmarket]['offset'];
            } catch (e) {
                gs.error("Error from Script Include MSS_Custody_Event_Utils - offset retrieval: " + e.message);
            }

            var marketSettlementBatch, settlementDateafterBatch, targetAfterSettlementDateBatch, settlementDateBatch;
            try {
                // MSSCUSTODY 5319 - Fetch require values for Core Expected transition time calculation
                marketSettlementBatch = this.marketBatchProcessStatus[eventstatusmarket]['mSettlementDateBatch'];
                settlementDateafterBatch = this.marketBatchProcessStatus[eventstatusmarket]['sDateafterBatch'];
                targetAfterSettlementDateBatch = this.marketBatchProcessStatus[eventstatusmarket]['tSDateafterBatch'];
                settlementDateBatch = this.marketBatchProcessStatus[eventstatusmarket]['sDateBatch'];
            } catch (e) {
                gs.error("Error from Script Include MSS_Custody_Event_Utils - market batch process status retrieval: " + e.message);
            }

            var currentTime;

            var dayLightFlag = gs.getProperty('x_hsb11_mss_custod.isDayLightsSavingOnMarketBatch');
            var daylighthr;
            var additionalhr = (dayLightFlag.toString() == 'true') ? 3600 : 0; // MSSCUSTODY-7080

            if (offse) {
                daylighthr = (parseInt(offse, 10) + additionalhr).toString();
            } else {
                daylighthr = additionalhr.toString();
            }

            try {
                // MSSCUSTODY 5319 - Converted event time to UTC timezone
                currentTime = new GlideScheduleDateTime(eventDateTime);
                currentTime.setTimeZone("UTC");
                currentTime.addSeconds(daylighthr);
            } catch (e) {
                gs.error("Error from Script Include MSS_Custody_Event_Utils - currentTime initialization: " + e.message);
            }

            var time, timeSplit, coreSSLUTimeInt;
            try {
                time = currentTime.getGlideDateTime().toString().split(" ")[1];
                timeSplit = time.split(":");
                coreSSLUTimeInt = timeSplit[0] + timeSplit[1];
            } catch (e) {
                gs.error("Error from Script Include MSS_Custody_Event_Utils - time parsing: " + e.message);
            }

            var isNextDate = false;
            var nextAvailableTime = -1;

            try {
                //set value to nextAvailableTime if there're still batch(es) later today
                if (appropriateBatch.indexOf(',') != -1) { // If Multiple Values are present differentiated via ,
                    var ttime = appropriateBatch.split(',');

                    for (var i = 0; i < ttime.length; i++) {
                        if (coreSSLUTimeInt < ttime[i] && (nextAvailableTime === -1 || ttime[i] < nextAvailableTime)) {
                            nextAvailableTime = ttime[i];
                        }
                    }
                } else { // If a single value
                    if (coreSSLUTimeInt < appropriateBatch) {
                        nextAvailableTime = appropriateBatch;
                    }
                }

            } catch (e) {
                gs.error("Error from Script Include MSS_Custody_Event_Utils - nextAvailableTime calculation: " + e.message);
            }

            try {

                // If a trade is received after the last batch, the trigger has to be based on the next rule
                if (nextAvailableTime === -1) { // today's batch(es) are already processed
                    isNextDate = true;

                    if (!nextDayBatch || nextDayBatch == 'Exception' || nextDayBatch == 'aNaN') { //MSSCUSTODY-7186: Introduced additional checks for nextDayBatch
                        return 'Exception';
                    } else { // will be the earliest batch on the next day

                        if (nextDayBatch.indexOf(',') != -1) { // If multiple values are present, differentiated via ','
                            try {

                                var ntime = nextDayBatch.split(',');
                                for (var i = 0; i < ntime.length; i++) {
                                    if (nextAvailableTime === -1 || ntime[i] < nextAvailableTime) {
                                        nextAvailableTime = ntime[i];

                                    }
                                }
                            } catch (e) {
                                gs.error("Error from Script Include MSS_Custody_Event_Utils - getCoreExpectedTransDateTime - multiple values are present: " + e.message);
                            }


                        } else { // If a single value in the next day batch

                            nextAvailableTime = nextDayBatch;
                            try {
                                // MSSCUSTODY 5319 - Added below logic to handle case creation when event comes on SD-1 after all batches are complete
                                if ((nextAvailableTime === settlementDateBatch || nextAvailableTime === targetAfterSettlementDateBatch) &&
                                    (marketSettlementBatch === '0000' || settlementDateafterBatch === '0000')) {


                                    if (nextAvailableTime === settlementDateBatch) {
                                        try {
                                            var batchHour = settlementDateBatch.slice(0, 2);
                                            var batchMinute = settlementDateBatch.slice(2, 4);
                                            var batchTime = batchHour + ":" + batchMinute + ":00";

                                            var adjustedDate = new GlideDateTime(settlementDate);
                                            if (schedule === 'Europe/London') {
                                                adjustedDate = adjustedDate.getLocalDate() + " " + batchTime;

                                            } else {
                                                adjustedDate.addDaysLocalTime(-1);
                                                adjustedDate = adjustedDate.getLocalDate() + " " + batchTime;
                                            }

                                            var gdtSettlementDate = new GlideScheduleDateTime(adjustedDate);
                                            gdtSettlementDate.setTimeZone(schedule);

                                            return gdtSettlementDate;
                                        } catch (e) {
                                            gs.error("Error from Script Include MSS_Custody_Event_Utils - getCoreExpectedTransDateTime - nextAvailableTime === settlementDateBatch: " + e.message);
                                        }

                                    } else if (nextAvailableTime === targetAfterSettlementDateBatch) {
                                        try {


                                            var batchHour = targetAfterSettlementDateBatch.slice(0, 2);
                                            var batchMinute = targetAfterSettlementDateBatch.slice(2, 4);
                                            var batchTime = batchHour + ":" + batchMinute + ":00";

                                            var adjustedDate = new GlideDateTime(settlementDate);
                                            if (schedule === 'Europe/London') {
                                                adjustedDate.addDaysLocalTime(1);
                                            }
                                            var settlementDateWithBatchTime = adjustedDate.getLocalDate() + " " + batchTime;


                                            var gdtSettlementDate = new GlideScheduleDateTime(settlementDateWithBatchTime);
                                            gdtSettlementDate.setTimeZone(schedule);


                                            return gdtSettlementDate;
                                        } catch (e) {
                                            gs.error("Error from Script Include MSS_Custody_Event_Utils - getCoreExpectedTransDateTime - nextAvailableTime === targetAfterSettlementDateBatch: " + e.message);
                                        }
                                    }
                                }
                            } catch (e) {
                                gs.error("Error from Script Include MSS_Custody_Event_Utils - getCoreExpectedTransDateTime - case creation when event comes on SD-1: " + e.message);
                            }
                        }
                    }
                }
            } catch (e) {
                gs.error("Error from Script Include MSS_Custody_Event_Utils - getCoreExpectedTransDateTime - next day batch processing: " + e.message);
            }

            var date;
            try {
                date = new GlideDateTime(eventDateTime);
                if (isNextDate) {
                    date.addDaysLocalTime(1);

                }
            } catch (e) {
                gs.error("Error from Script Include MSS_Custody_Event_Utils - date adjustment: " + e.message);
            }

            var tt, hour, min, timef, nxtTime, coreExpectedTransitionTime;
            try {

                tt = nextAvailableTime.toString();
                hour = tt.slice(0, -2).padStart(2, '0');
                min = tt.slice(-2).padStart(2, '0');
                timef = hour + ":" + min + ":00";

                nxtTime = date.getDate().toString() + " " + timef;
                coreExpectedTransitionTime = new GlideScheduleDateTime(nxtTime);
                coreExpectedTransitionTime.setTimeZone("UTC");

            } catch (e) {
                gs.error("Error from Script Include MSS_Custody_Event_Utils - final transition time calculation: " + e.message);
            }

            return coreExpectedTransitionTime;

        } catch (e) {
            gs.error("Error from Script Include MSS_Custody_Event_Utils - getCoreExpectedTransDateTime: " + e.message);
        }
    },

    //Below function is created as per MSSCUSTODY-3037: Create region field to trade form
    getOwningBusinessRegion: function(OwningBusinessName, objectid) {
        try {
            var region = '';
            var grRegion = new GlideRecord('x_hsb11_mss_c_proc_custody_location_code');
            grRegion.addQuery('owning_business', OwningBusinessName);
            grRegion.query();
            if (grRegion.next()) { //MSSCUSTODY-8224 - added adtional bracket if was without bracket
                region = grRegion.region;
            } else { //MSSCUSTODY-8224 
                var invalidMarketLog = "-->Region population failed due to missing record in Custody Location Codes for market " + OwningBusinessName + "\n";
                this.tradeInvalidDataLogs(invalidMarketLog, objectid);
            } //MSSCUSTODY-8224 
            return region;
        } catch (e) {
            gs.error("Error from Script Include MSS_Custody_Event_Utils - getOwningBusinessRegion: " + e.message);
        }
    },

    evalAmendCase: function(tradeId) {
        try {
            var getTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            if (getTrade.get(tradeId)) {
                var getCase = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
                getCase.addEncodedQuery('trade_id.sys_id=' + getTrade.sys_id + '^stateNOT IN3,4,7^amend_case=True^ORamend_case=confSettle'); //7964
                getCase.query();
                if (getCase.next()) {
                    return true;
                } else {
                    return false;
                }
            }
            return false;
        } catch (e) {
            gs.error("Error from Script Include MSS_Custody_Event_Utils - evalAmendCase (for trade " + tradeId + "): " + e.message);
        }
    },

    tradeInvalidDataLogs: function(newLog, tradeID) { //MSSCUSTODY-8224 - New function for logging details

        try {
            var finalLogs = [];
            var logData = new GlideRecord('x_hsb11_mss_custod_mss_custody_event_inbound_staging');
            logData.addEncodedQuery('object_id=' + tradeID);
            logData.orderByDesc('sys_created_on');
            logData.query();
            if (logData.next()) {
                if (logData.invalid_data == "") { //heading only for the very first time
                    finalLogs.push("The below received data are not expected as per iQube Configuration/tradeDataConfigs property - x_hsb11_mss_custod.tradeDataConfigs  " + "\n");
                }
                finalLogs.push(logData.invalid_data)
                finalLogs.push(newLog)
                logData.invalid_data = finalLogs.toString().replaceAll(",", "")
                logData.update();
            }
        } catch (ex) {
            gs.info('Error Received from tradeInvalidDataLogs' + ex)
        }

    }, //MSSCUSTODY-8224 - New function for logging details


    type: 'MSS_Custody_Event_Utils'
};
